<div class="stack"><div><h1><?php echo $item ? 'Modifica categoria' : 'Nuova categoria'; ?></h1><p class="muted">Gestisci nome, icona e testo introduttivo.</p></div><form class="panel form-grid" action="<?php echo e(url('/admin/categories/save')); ?>" method="post"><?php echo csrf_field(); ?><?php if ($item): ?><input type="hidden" name="id" value="<?php echo e((string) $item['id']); ?>"><?php endif; ?><div class="form-group"><label>Nome</label><input class="form-control" name="name" value="<?php echo e($item['name'] ?? ''); ?>" required></div><div class="form-group"><label>Icona</label><input class="form-control" name="icon" value="<?php echo e($item['icon'] ?? '🏷️'); ?>"></div><div class="form-group"><label>Numero offerte</label><input class="form-control" name="offer_count" type="number" value="<?php echo e((string) ($item['offer_count'] ?? 0)); ?>"></div><div class="form-group form-group-full"><label>Descrizione</label><textarea class="form-textarea" rows="4" name="description"><?php echo e($item['description'] ?? ''); ?></textarea></div><div class="form-group-full"><button class="btn" type="submit">Salva categoria</button></div></form></div>
